{"chunk_id":"b581e0","wall_time_seconds":0.000005067,"exit_code":0,"original_token_count":2525,"output":""""Input discovery helpers for local zizmor inputs."""
from dataclasses import dataclass
from pathlib import Path
import fnmatch
import os
import re


@dataclass
class Input:
    path: str
    kind: str
    text: str


def classify(path: str, text: str) -> str | None:
    name = Path(path).name.lower()
    if name in ('dependabot.yml', 'dependabot.yaml') or '.github/dependabot.' in path.replace('\\', '/'):
        return 'dependabot'
    if name in ('action.yml', 'action.yaml'):
        return 'actions'
    if '/.github/workflows/' in ('/' + path.replace('\\', '/')):
        return 'workflows'
    if re.search(r'(?m)^\s*(?:on|jobs)\s*:', text):
        return 'workflows'
    if re.search(r'(?m)^\s*(?:runs|inputs|outputs)\s*:', text):
        return 'actions'
    if re.search(r'(?m)^\s*updates\s*:', text):
        return 'dependabot'
    return None


def _ignored(rel: str, rules: list[str]) -> bool:
    ignored = False
    for line in rules:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        negate = line.startswith('!')
        pat = line[1:] if negate else line
        pat = pat.rstrip('/')
        matched = fnmatch.fnmatch(rel, pat) or fnmatch.fnmatch('/' + rel, pat)
        if matched:
            ignored = negate
    return ignored


def _read(path: Path, given: str, explicit: bool = False):
    try:
        data = path.read_text(encoding='utf-8')
    except (OSError, UnicodeError):
        return None
    kind = classify(given, data)
    if explicit and kind is None:
        # Explicit YAML files are passed to the validator as candidate inputs.
        if path.suffix.lower() in ('.yml', '.yaml'):
            kind = 'workflows'
    return Input(given, kind, data) if kind else None


def collect(paths, kinds=None, stdin_text=None, respect_gitignore=True):
    """Return (inputs, invalid_paths); kinds uses workflows/actions/dependabot/all."""
    kinds = set(kinds or ('workflows', 'actions', 'dependabot'))
    if 'all' in kinds or 'default' in kinds:
        kinds = {'workflows', 'actions', 'dependabot'}
    records, invalid = [], []
    if '-' in paths:
        if len(paths) != 1:
            return [], list(paths)
        content = stdin_text if stdin_text is not None else ''
        kind = classify('stdin.yml', content)
        if kind in kinds:
            records.append(Input('<stdin>', kind, content))
        return records, invalid
    for value in paths:
        p = Path(value)
        if not p.exists():
            invalid.append(value)
            continue
        if p.is_file():
            rec = _read(p, value, True)
            if rec and rec.kind in kinds:
                records.append(rec)
            else:
                invalid.append(value)
            continue
        if not p.is_dir():
            invalid.append(value)
            continue
        root = p.resolve()
        ignore_rules = []
        if respect_gitignore:
            for ig in root.rglob('.gitignore'):
                try:
                    ignore_rules += ig.read_text(errors='replace').splitlines()
                except OSError:
                    pass
        for child in sorted(root.rglob('*')):
            if not child.is_file():
                continue
            rel = child.relative_to(root).as_posix()
            if respect_gitignore and _ignored(rel, ignore_rules):
                continue
            rec = _read(child, str(child))
            if rec and rec.kind in kinds:
                records.append(rec)
    return records, invalid
"""Small handlers for zizmor's informational command-line modes."""
from pathlib import Path
import sys

VERSION = "zizmor 1.25.2\n"
SHELLS = {"bash", "elvish", "fish", "nushell", "powershell", "zsh"}
BASE = Path(__file__).with_name("cli_completions")


def handle(argv):
    """Return (handled, stdout, stderr, status), or handled=False.

    Call before the main argument parser. It handles only modes that exit
    before auditing; ordinary arguments are left to the caller.
    """
    args = list(argv)
    if "--version" in args or "-V" in args:
        return True, VERSION, "", 0
    if "--help" in args or "-h" in args:
        return False, "", "", 0
    if "--completions" in args:
        try:
            i = args.index("--completions")
            shell = args[i + 1]
        except (ValueError, IndexError):
            return False, "", "", 0
        if shell not in SHELLS:
            return False, "", "", 0
        return True, (BASE / (shell + ".completion")).read_text(), "", 0
    if "--thanks" in args:
        if len(args) != 1:
            return False, "", "", 0
        return True, (BASE / "thanks.txt").read_text(), "", 0
    if "--lsp" in args and len(args) == 1:
        return True, "", "", 0
    return False, "", "", 0


def emit_if_handled(argv):
    handled, out, err, status = handle(argv)
    if handled:
        sys.stdout.write(out)
        sys.stderr.write(err)
        return status
    return None
"""Output helpers for zizmor-compatible formats."""
import json
import os


def _primary(finding):
    locs = finding.get("locations") or []
    for loc in locs:
        if (loc.get("symbolic") or {}).get("kind") == "Primary":
            return loc
    return locs[-1] if locs else {}


def _where(finding):
    loc = _primary(finding)
    sym = loc.get("symbolic") or {}
    key = sym.get("key") or {}
    local = key.get("Local") or {}
    path = local.get("given_path") or ""
    concrete = loc.get("concrete") or {}
    location = concrete.get("location") or {}
    start = location.get("start_point") or {}
    return path, int(start.get("row", 0)) + 1, sym.get("annotation") or ""


def github(findings):
    out = []
    for f in findings:
        if f.get("ignored"):
            continue
        path, line, annotation = _where(f)
        ident = f.get("ident", "finding")
        desc = f.get("desc", ident)
        msg = os.path.basename(path) + ":" + str(line) + ": " + desc
        if annotation:
            msg += ": " + annotation
        props = []
        if path:
            props.append("file=" + path.replace("%", "%25").replace("\r", "%0D").replace("\n", "%0A").replace(":", "%3A").replace(",", "%2C"))
        props += ["line=" + str(line), "title=" + ident]
        level = str((f.get("determinations") or {}).get("severity", "medium")).lower()
        cmd = "error" if level == "high" else "warning" if level == "medium" else "notice"
        out.append("::" + cmd + " " + ",".join(props) + "::" + msg.replace("%", "%25").replace("\r", "%0D").replace("\n", "%0A"))
    return "\n".join(out) + ("\n" if out else "")


def sarif(findings):
    """Render a compact SARIF 2.1.0 report from JSON-v1-shaped findings."""
    rules, results = {}, []
    for f in findings:
        ident = f.get("ident", "finding")
        url, desc = f.get("url", ""), f.get("desc", ident)
        rid = "zizmor/" + ident
        rules.setdefault(rid, {"id": rid, "name": ident, "helpUri": url,
            "help": {"text": desc, "markdown": "`" + ident + "`: " + desc + ("\n\nDocs: <" + url + ">" if url else "")},
            "properties": {"tags": ["security"]}})
        if f.get("ignored"):
            continue
        path, line, annotation = _where(f)
        locs = []
        for item in f.get("locations") or []:
            sym = item.get("symbolic") or {}
            con = item.get("concrete") or {}
            pos = con.get("location") or {}
            start, end = pos.get("start_point") or {}, pos.get("end_point") or {}
            k = (sym.get("key") or {}).get("Local") or {}
            p = k.get("given_path") or path
            a = sym.get("annotation") or ""
            physical = {"artifactLocation": {"uri": p}}
            if pos:
                physical["region"] = {"startLine": int(start.get("row", 0))+1,
                    "startColumn": int(start.get("column", 0))+1,
                    "endLine": int(end.get("row", start.get("row", 0)))+1,
                    "endColumn": int(end.get("column", start.get("column", 0)))+1,
                    "sourceLanguage": "yaml"}
                if con.get("feature") is not None:
                    physical["region"]["snippet"] = {"text": con["feature"]}
            logical = {"logicalLocations": [{"properties": {"symbolic": sym}}], "physicalLocation": physical}
            if a:
                logical["message"] = {"text": a}
            locs.append(logical)
        primary = next((x for x in locs if ((x.get("logicalLocations", [{}])[0].get("properties", {}).get("symbolic") or {}).get("kind") == "Primary")), None)
        if primary is None and locs:
            primary = locs[-1]
        det = f.get("determinations") or {}
        result = {"ruleId": rid, "kind": "fail", "level": "error" if det.get("severity") == "High" else "warning",
            "message": {"text": desc + (": " + annotation if annotation else "")},
            "properties": {"zizmor/confidence": det.get("confidence", "Medium"), "zizmor/persona": det.get("persona", "Regular"), "zizmor/severity": det.get("severity", "Medium")}}
        if primary:
            result["locations"] = [primary]
            result["codeFlows"] = [{"threadFlows": [{"locations": [{"importance": "essential" if x is primary else "important", "location": x} for x in locs]}]}]
        results.append(result)
    return {"$schema": "https://docs.oasis-open.org/sarif/sarif/v2.1.0/os/schemas/sarif-schema-2.1.0.json",
        "runs": [{"invocations": [{"executionSuccessful": True}], "results": results,
                 "tool": {"driver": {"name": "zizmor", "version": "1.25.2", "semanticVersion": "1.25.2",
                    "informationUri": "https://docs.zizmor.sh", "downloadUri": "https://github.com/zizmorcore/zizmor",
                    "rules": list(rules.values())}}}], "version": "2.1.0"}


def format_output(kind, findings):
    if kind == "github":
        return github(findings)
    if kind == "sarif":
        return json.dumps(sarif(findings), indent=2, ensure_ascii=False)
    raise ValueError("unsupported output format: " + kind)
"}

