"""Input discovery helpers for local zizmor inputs."""
from dataclasses import dataclass
from pathlib import Path
import fnmatch
import os
import re


@dataclass
class Input:
    path: str
    kind: str
    text: str


def classify(path: str, text: str, infer: bool = True) -> str | None:
    name = Path(path).name.lower()
    normalized = '/' + path.replace('\\', '/').lstrip('/')
    if name in ('dependabot.yml', 'dependabot.yaml') or '.github/dependabot.' in path.replace('\\', '/'):
        return 'dependabot'
    if name in ('action.yml', 'action.yaml'):
        return 'actions'
    if '/.github/workflows/' in normalized:
        return 'workflows'
    if not infer:
        return None
    if re.search(r'(?m)^\s*(?:on|jobs)\s*:', text):
        return 'workflows'
    if re.search(r'(?m)^\s*(?:runs|inputs|outputs)\s*:', text):
        return 'actions'
    if re.search(r'(?m)^\s*updates\s*:', text):
        return 'dependabot'
    return None


def _ignored(rel: str, rules: list[tuple[str, str]]) -> bool:
    ignored = False
    for base, line in rules:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if line.startswith('\\#') or line.startswith('\\!'):
            line = line[1:]
        negate = line.startswith('!')
        pat = line[1:] if negate else line
        pat = pat.rstrip('/')
        sub = rel[len(base):].lstrip('/') if base and rel.startswith(base + '/') else ('' if rel == base else None)
        if sub is None:
            continue
        if pat.startswith('/'):
            pat = pat[1:]
            matched = fnmatch.fnmatch(sub, pat)
        elif '/' in pat:
            matched = fnmatch.fnmatch(sub, pat)
        else:
            matched = any(fnmatch.fnmatch(part, pat) for part in sub.split('/'))
        if matched:
            ignored = negate
    return ignored


def _read(path: Path, given: str, explicit: bool = False):
    try:
        data = path.read_text(encoding='utf-8')
    except (OSError, UnicodeError):
        return None
    kind = classify(given, data, infer=explicit)
    if explicit and kind is None:
        # Explicit YAML files are passed to the validator as candidate inputs.
        if path.suffix.lower() in ('.yml', '.yaml'):
            kind = 'workflows'
    return Input(given, kind, data) if kind else None


def collect(paths, kinds=None, stdin_text=None, respect_gitignore=True):
    """Return (inputs, invalid_paths); kinds uses workflows/actions/dependabot/all."""
    kinds = set(kinds or ('workflows', 'actions', 'dependabot'))
    if 'all' in kinds or 'default' in kinds:
        kinds = {'workflows', 'actions', 'dependabot'}
    records, invalid = [], []
    if '-' in paths:
        if len(paths) != 1:
            return [], list(paths)
        content = stdin_text if stdin_text is not None else ''
        kind = classify('stdin.yml', content)
        if kind:
            records.append(Input('<stdin>', kind, content))
        return records, invalid
    for value in paths:
        p = Path(value)
        if not p.exists():
            invalid.append(value)
            continue
        if p.is_file():
            rec = _read(p, value, True)
            # --collect controls only repository discovery, never explicit inputs.
            if rec:
                records.append(rec)
            else:
                invalid.append(value)
            continue
        if not p.is_dir():
            invalid.append(value)
            continue
        root = p.resolve()
        ignore_rules = []
        if respect_gitignore:
            for ig in sorted(root.rglob('.gitignore'), key=lambda p: len(p.relative_to(root).parts)):
                try:
                    base = ig.parent.relative_to(root).as_posix()
                    if base == '.':
                        base = ''
                    ignore_rules += [(base, line) for line in ig.read_text(errors='replace').splitlines()]
                except OSError:
                    pass
        for child in sorted(root.rglob('*')):
            if not child.is_file():
                continue
            rel = child.relative_to(root).as_posix()
            if respect_gitignore and _ignored(rel, ignore_rules):
                continue
            rec = _read(child, str(child))
            if rec and rec.kind in kinds:
                records.append(rec)
    return records, invalid

